/**
 * TypeScript port of engine/predictpro_engine (types, stats, Elo, rating book).
 * Kept line-for-line equivalent to the Python engine; `engine.test.ts` checks parity
 * against fixtures generated by the Python implementation.
 */

export type Outcome = 'home' | 'draw' | 'away';
export type Confidence = 'low' | 'medium' | 'high';
export type Favours = 'home' | 'away' | 'neutral';

export type FinishedMatch = {
  id: string;
  date: Date;
  home: string;
  away: string;
  homeScore: number;
  awayScore: number;
  competition: string;
  neutral: boolean;
};

export type GameRecord = { date: Date; opponent: string; isHome: boolean; scored: number; conceded: number; competition: string; result: 'W' | 'D' | 'L' };

export type Absence = { player: string; position: string; importance: number; reason: string; tag?: string | null };

export function absenceWeight(a: Absence): number {
  const w = Math.max(0, Math.min(1, a.importance));
  return w * (a.reason === 'doubtful' ? 0.5 : 1);
}

export type TeamState = {
  team: string;
  name: string;
  elo: number;
  games: number;
  attack: number;
  defence: number;
  pointsFor: number | null;
  pointsAgainst: number | null;
  recent: GameRecord[]; // newest first
  lastPlayed: Date | null;
  streaks: Record<string, number>;
};

export type MatchInput = {
  sport: string;
  competition: string;
  kickoff: Date;
  home: TeamState;
  away: TeamState;
  neutral: boolean;
  homeAbsences: Absence[];
  awayAbsences: Absence[];
  h2h: FinishedMatch[]; // newest first
  leagueAvgHome: number | null;
  leagueAvgAway: number | null;
};

export type KeyFactor = { text: string; impact: number; favours: Favours; category: string };

export type Prediction = {
  sport: string;
  model: string;
  modelVersion: string;
  probHome: number;
  probDraw: number | null;
  probAway: number;
  predictedHome: number;
  predictedAway: number;
  expectedHome: number;
  expectedAway: number;
  confidence: Confidence;
  keyFactors: KeyFactor[];
  explanation: { method: string; summary: string; steps: { title: string; detail: string }[]; inputs: Record<string, unknown> };
};

export function probabilities(p: Pick<Prediction, 'probHome' | 'probDraw' | 'probAway'>): Partial<Record<Outcome, number>> {
  const out: Partial<Record<Outcome, number>> = { home: p.probHome, away: p.probAway };
  if (p.probDraw !== null) out.draw = p.probDraw;
  return out;
}

/** First key with the maximum value (same tie-break as Python's max over a dict). */
export function argmax(probs: Partial<Record<Outcome, number>>): Outcome {
  let best: Outcome = 'home';
  let bestV = -Infinity;
  for (const k of Object.keys(probs) as Outcome[]) {
    if ((probs[k] as number) > bestV) {
      best = k;
      bestV = probs[k] as number;
    }
  }
  return best;
}

export function outcomeOf(h: number, a: number): Outcome {
  return h > a ? 'home' : h < a ? 'away' : 'draw';
}

// ------------------------------------------------------------------ number helpers
/** Python's round(): half-to-even. */
export function pyRound(x: number, nd = 0): number {
  const m = 10 ** nd;
  const v = x * m;
  const f = Math.floor(v);
  const diff = v - f;
  let r: number;
  if (Math.abs(diff - 0.5) < 1e-9) r = f % 2 === 0 ? f : f + 1;
  else r = Math.round(v);
  return r / m;
}

export const fmt0 = (x: number) => x.toFixed(0);
export const pct0 = (x: number) => `${(x * 100).toFixed(0)}%`;
export const signed = (x: number, d = 1) => `${x >= 0 ? '+' : ''}${x.toFixed(d)}`;
export const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));

// ------------------------------------------------------------------ stats
function lgamma(n: number): number {
  // n is a non-negative integer here: log((n)!) with n = k+1
  let s = 0;
  for (let i = 2; i < n; i++) s += Math.log(i);
  return s;
}

export function poissonPmf(k: number, lam: number): number {
  if (k < 0) return 0;
  if (lam <= 0) return k === 0 ? 1 : 0;
  return Math.exp(k * Math.log(lam) - lam - lgamma(k + 1));
}

export function dixonColesTau(i: number, j: number, lh: number, la: number, rho: number): number {
  if (i === 0 && j === 0) return 1 - lh * la * rho;
  if (i === 0 && j === 1) return 1 + lh * rho;
  if (i === 1 && j === 0) return 1 + la * rho;
  if (i === 1 && j === 1) return 1 - rho;
  return 1;
}

export function scoreMatrix(lh: number, la: number, maxGoals = 10, rho = 0): number[][] {
  const ph = Array.from({ length: maxGoals + 1 }, (_, i) => poissonPmf(i, lh));
  const pa = Array.from({ length: maxGoals + 1 }, (_, j) => poissonPmf(j, la));
  const grid = ph.map((x, i) => pa.map((y, j) => Math.max(0, x * y * dixonColesTau(i, j, lh, la, rho))));
  const total = grid.reduce((s, row) => s + row.reduce((a, b) => a + b, 0), 0);
  return grid.map((row) => row.map((p) => p / total));
}

export function outcomeProbabilities(grid: number[][]): [number, number, number] {
  let h = 0;
  let d = 0;
  let a = 0;
  grid.forEach((row, i) =>
    row.forEach((p, j) => {
      if (i > j) h += p;
      else if (i === j) d += p;
      else a += p;
    }),
  );
  return [h, d, a];
}

export function mostLikelyScore(grid: number[][], outcome: Outcome): [number, number] {
  let best: [number, number] = [0, 0];
  let bestP = -1;
  grid.forEach((row, i) =>
    row.forEach((p, j) => {
      const ok = (outcome === 'home' && i > j) || (outcome === 'away' && i < j) || (outcome === 'draw' && i === j);
      if (ok && p > bestP) {
        best = [i, j];
        bestP = p;
      }
    }),
  );
  return best;
}

/** Standard normal CDF (Abramowitz-Stegun erf, |error| < 1.5e-7). */
export function normalCdf(x: number): number {
  const z = x / Math.SQRT2;
  const t = 1 / (1 + 0.3275911 * Math.abs(z));
  const y = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z);
  const erf = z >= 0 ? y : -y;
  return 0.5 * (1 + erf);
}

/** Inverse standard normal CDF (Acklam's algorithm). */
export function normalInv(p: number): number {
  const a = [-3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2, -3.066479806614716e1, 2.506628277459239];
  const b = [-5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1, -1.328068155288572e1];
  const c = [-7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416];
  const q0 = clamp(p, 1e-9, 1 - 1e-9);
  if (q0 < 0.02425) {
    const q = Math.sqrt(-2 * Math.log(q0));
    return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
  }
  if (q0 > 1 - 0.02425) {
    const q = Math.sqrt(-2 * Math.log(1 - q0));
    return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
  }
  const q = q0 - 0.5;
  const r = q * q;
  return ((((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q) / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1);
}

// ------------------------------------------------------------------ Elo
export type EloConfig = { k: number; homeAdvantage: number; initial: number; seasonGapDays: number; seasonRegression: number };

export function expectedScore(ra: number, rb: number, advA = 0): number {
  return 1 / (1 + 10 ** (-(ra + advA - rb) / 400));
}

export function footballMovMultiplier(gd: number): number {
  const g = Math.abs(gd);
  if (g <= 1) return 1;
  if (g === 2) return 1.5;
  return (11 + g) / 8;
}

export function basketballMovMultiplier(pointDiff: number, winnerEloDiff: number): number {
  return (Math.abs(pointDiff) + 3) ** 0.8 / (7.5 + 0.006 * winnerEloDiff);
}

export function eloUpdate(rh: number, ra: number, actualHome: number, k: number, ha: number, mult = 1): [number, number] {
  const delta = k * mult * (actualHome - expectedScore(rh, ra, ha));
  return [rh + delta, ra - delta];
}

// ------------------------------------------------------------------ rating book
const DAY = 86_400_000;

export function sortMatches(ms: FinishedMatch[]): FinishedMatch[] {
  return [...ms].sort((x, y) => x.date.getTime() - y.date.getTime() || (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
}

export abstract class RatingBook {
  abstract sport: string;
  elo = new Map<string, number>();
  games = new Map<string, number>();
  recent = new Map<string, GameRecord[]>();
  lastPlayed = new Map<string, Date>();
  streaks = new Map<string, Record<string, number>>();
  private h2hMap = new Map<string, FinishedMatch[]>();
  lastDate: Date | null = null;
  matchesProcessed = 0;

  constructor(
    public eloCfg: EloConfig,
    public recentN = 10,
    public h2hN = 6,
  ) {}

  rating(team: string): number {
    if (!this.elo.has(team)) this.elo.set(team, this.eloCfg.initial);
    return this.elo.get(team)!;
  }

  updateMany(ms: FinishedMatch[]) {
    for (const m of sortMatches(ms)) this.update(m);
  }

  update(m: FinishedMatch) {
    if (this.lastDate && m.date.getTime() < this.lastDate.getTime()) throw new Error(`matches must be replayed in chronological order (${m.id})`);
    for (const t of [m.home, m.away]) this.maybeNewSeason(t, m.date);
    const he = this.rating(m.home);
    const ae = this.rating(m.away);
    this.updateStats(m);
    const ha = m.neutral ? 0 : this.eloCfg.homeAdvantage;
    const actual = m.homeScore > m.awayScore ? 1 : m.homeScore < m.awayScore ? 0 : 0.5;
    const mult = this.movMultiplier(m, he + ha - ae);
    const [nh, na] = eloUpdate(he, ae, actual, this.eloCfg.k, ha, mult);
    this.elo.set(m.home, nh);
    this.elo.set(m.away, na);
    this.push(m.home, { date: m.date, opponent: m.away, isHome: true, scored: m.homeScore, conceded: m.awayScore, competition: m.competition, result: res(m.homeScore, m.awayScore) });
    this.push(m.away, { date: m.date, opponent: m.home, isHome: false, scored: m.awayScore, conceded: m.homeScore, competition: m.competition, result: res(m.awayScore, m.homeScore) });
    const key = pairKey(m.home, m.away);
    const list = this.h2hMap.get(key) ?? [];
    list.unshift(m);
    if (list.length > this.h2hN) list.length = this.h2hN;
    this.h2hMap.set(key, list);
    for (const [team, scored, conceded] of [
      [m.home, m.homeScore, m.awayScore],
      [m.away, m.awayScore, m.homeScore],
    ] as const) {
      this.games.set(team, (this.games.get(team) ?? 0) + 1);
      this.lastPlayed.set(team, m.date);
      const st = this.streaks.get(team) ?? { win: 0, loss: 0, unbeaten: 0, winless: 0 };
      const won = scored > conceded;
      const lost = scored < conceded;
      st.win = won ? st.win + 1 : 0;
      st.loss = lost ? st.loss + 1 : 0;
      st.unbeaten = lost ? 0 : st.unbeaten + 1;
      st.winless = won ? 0 : st.winless + 1;
      this.streaks.set(team, st);
    }
    this.lastDate = m.date;
    this.matchesProcessed += 1;
  }

  private push(team: string, r: GameRecord) {
    const l = this.recent.get(team) ?? [];
    l.unshift(r);
    if (l.length > this.recentN) l.length = this.recentN;
    this.recent.set(team, l);
  }

  private maybeNewSeason(team: string, date: Date) {
    const last = this.lastPlayed.get(team);
    if (last && Math.floor((date.getTime() - last.getTime()) / DAY) >= this.eloCfg.seasonGapDays) {
      const r = this.rating(team);
      this.elo.set(team, r + (this.eloCfg.initial - r) * this.eloCfg.seasonRegression);
      this.regressStats(team);
    }
  }

  protected abstract updateStats(m: FinishedMatch): void;
  protected abstract regressStats(team: string): void;
  protected movMultiplier(_m: FinishedMatch, _eloDiffHome: number): number {
    return 1;
  }
  leagueAverages(_competition: string): [number | null, number | null] {
    return [null, null];
  }

  headToHead(a: string, b: string): FinishedMatch[] {
    return [...(this.h2hMap.get(pairKey(a, b)) ?? [])];
  }

  teamState(team: string, name?: string): TeamState {
    return {
      team,
      name: name ?? team,
      elo: this.rating(team),
      games: this.games.get(team) ?? 0,
      attack: 1,
      defence: 1,
      pointsFor: null,
      pointsAgainst: null,
      recent: [...(this.recent.get(team) ?? [])],
      lastPlayed: this.lastPlayed.get(team) ?? null,
      streaks: this.streaks.has(team) ? { ...this.streaks.get(team)! } : {},
    };
  }

  buildInput(o: { home: string; away: string; kickoff: Date; competition?: string; neutral?: boolean; homeAbsences?: Absence[]; awayAbsences?: Absence[]; homeName?: string; awayName?: string }): MatchInput {
    const comp = o.competition ?? 'default';
    const [ah, aa] = this.leagueAverages(comp);
    return {
      sport: this.sport,
      competition: comp,
      kickoff: o.kickoff,
      home: this.teamState(o.home, o.homeName),
      away: this.teamState(o.away, o.awayName),
      neutral: !!o.neutral,
      homeAbsences: o.homeAbsences ?? [],
      awayAbsences: o.awayAbsences ?? [],
      h2h: this.headToHead(o.home, o.away),
      leagueAvgHome: ah,
      leagueAvgAway: aa,
    };
  }

  ratingsTable(): [string, number][] {
    return [...this.elo.entries()].sort((a, b) => b[1] - a[1]);
  }
}

function res(s: number, c: number): 'W' | 'D' | 'L' {
  return s > c ? 'W' : s < c ? 'L' : 'D';
}

function pairKey(a: string, b: string): string {
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}
